import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';
import Navbar from './components/Navbar';

// Page Components
import Login from './components/Login';
import Register from './components/Register';
import AdminLogin from './components/AdminLogin';
import Dashboard from './components/Dashboard';
import SimpleLogin from './components/SimpleLogin';
import SimpleRegister from './components/SimpleRegister';
import SimpleAdminLogin from './components/SimpleAdminLogin';
import FixedAdminLogin from './components/FixedAdminLogin';
import AdminOnlyAnalytics from './components/AdminOnlyAnalytics';
import SimpleAnalytics from './components/SimpleAnalytics';
import AdminDashboard from './components/AdminDashboard';
import MovieList from './components/MovieList';
import Booking from './components/Booking';
import Analytics from './components/Analytics';

function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="App">
          <Navbar />
          <Routes>
            {/* Public Routes */}
            <Route path="/" element={<MovieList />} />
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
            <Route path="/admin-login" element={<AdminLogin />} />
            <Route path="/simple-login" element={<SimpleLogin />} />
            <Route path="/simple-register" element={<SimpleRegister />} />
            <Route path="/simple-admin-login" element={<SimpleAdminLogin />} />
            <Route path="/movies" element={<MovieList />} />
            <Route path="/booking/:movieId" element={<Booking />} />

            {/* Protected Routes */}
            <Route 
              path="/dashboard" 
              element={
                <ProtectedRoute>
                  <EnhancedDashboard />
                </ProtectedRoute>
              } 
            />
            <Route 
              path="/admin" 
              element={
                <ProtectedRoute>
                  <AdminOnlyAnalytics />
                </ProtectedRoute>
              } 
            />
            <Route 
              path="/analytics" 
              element={
                <ProtectedRoute>
                  <AdminOnlyAnalytics />
                </ProtectedRoute>
              } 
            />

            {/* Default Route */}
            <Route path="/" element={<MovieList />} />
          </Routes>
        </div>
      </Router>
    </AuthProvider>
  );
}

export default App;
